const disabledNotice=text=>`<aside class="ms-notice">${p(text)}<a href="#notes">Notes and downloads</a></aside>`;
let views=new WeakMap();
export function resetMarketSignsView(){views=new WeakMap();}
function local(state,owner){
 let v=views.get(state);const root=state.signs,group=['endings','patterns','crates'].includes(root?.practiceGroup)?root.practiceGroup:'prefix',holder=group==='prefix'?root:root?.[group],job=holder?.currentId??null,view=root?.view??'choose',recordSource=holder?.records?.[job]?.source;
 if(!v||v.owner!==owner||v.rootRef!==root||v.sourceRef!==root?.source||v.recordSourceRef!==recordSource||v.patternRef!==root?.patterns||v.patternSourceRef!==root?.patterns?.source||v.crateRef!==root?.crates||v.crateSourceRef!==root?.crates?.source){v={owner,rootRef:root,sourceRef:root?.source,recordSourceRef:recordSource,patternRef:root?.patterns,patternSourceRef:root?.patterns?.source,crateRef:root?.crates,crateSourceRef:root?.crates?.source,crateWord:root?.crates?.currentWordId,crateOpen:[],meaningPage:0,group,job,view,selected:null,panels:[],steps:{},practicePages:{},keptPage:0,longer:false};views.set(state,v);}
 if(v.group!==group||v.job!==job||v.view!==view){v.group=group;v.job=job;v.view=view;v.selected=null;v.steps={};v.panels=[];v.keptPage=0;v.crateOpen=[];}
 if(v.crateWord!==root?.crates?.currentWordId){v.crateWord=root?.crates?.currentWordId;v.crateOpen=[];v.steps={};}
 return v;
}
const panel=(v,id,label,body)=>`<details data-ms-panel="${id}"${v.panels.includes(id)?' open':''}><summary>${esc(label)}</summary>${body}</details>`;
function teaching(cards,v,patterns=false){return panel(v,'teaching','How the words work',c.readableMarketCards(cards).map((card,i)=>{
 const n=Math.min(v.steps[i]??0,card.steps.length);
 return `<section class="ms-teach"><h3>${esc(card.title)}</h3>${patterns?p('A true thing about language'):''}${p(card.text)}<h4>Worked example</h4>${patterns?p('A story from Willowbank'):''}${p(card.example)}<ol class="ms-steps">${card.steps.slice(0,n).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="ms-actions">${button('step-prev','Previous example part',`data-ms-card="${i}"`,n===0)}${button('step-next','Next example part',`data-ms-card="${i}"`,n===card.steps.length)}</div></section>`;
 }).join(''));}
function signArt(){return `<svg class="ms-sign-art" viewBox="0 0 600 230" aria-hidden="true"><path d="M279 202v28h42v-28" fill="#836442"/><path d="m25 20 13 177 519 9 20-183Z" fill="#fffdf5" stroke="#836442" stroke-width="7"/><path d="m41 35 508-1M42 182l503 9" fill="none" stroke="#e4caa4" stroke-width="3"/><circle cx="55" cy="58" r="5" fill="#836442"/><circle cx="547" cy="58" r="5" fill="#836442"/></svg>`;}
function prefixBench(v,l){
 const s=v.prefixSource,d=v.prefixDraft;if(!s||!d)return disabledNotice(T.prefixUnavailable);if(!s.prefixes.length||!s.parts.length)return disabledNotice(T.emptyParts);
 const r=c.marketPrefixResult(s,d),prefix=s.prefixes.find(x=>x.id===d.prefixId),part=s.parts.find(x=>x.id===d.partId),ready=r?.kind!=='incomplete';
 const letters=ready?r.boundary?`<span class="ms-prefix">${esc(prefix.text.slice(0,-1))}<mark>${esc(r.boundary)}</mark></span><span class="ms-part"><mark>${esc(r.boundary)}</mark>${esc(part.text.slice(1))}</span>`:`<span class="ms-prefix">${esc(prefix.text)}</span><span class="ms-part">${esc(part.text)}</span>`:'';
 const kept=d.kept,perPage=6,pages=Math.max(1,Math.ceil(kept.length/perPage)),page=Math.min(l.keptPage,pages-1);
 return `<section class="ms-prefix-bench"><h2 id="ms-task" tabindex="-1">The Prefix Signs</h2>${p('Pick a prefix. Pick a word part. Watch them join.')}<div class="ms-selects"><label>Prefix<select data-ms-prefix><option value=""${!prefix?' selected':''}>Choose a prefix</option>${s.prefixes.map(x=>`<option value="${esc(x.id)}"${x.id===d.prefixId?' selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label>Word part<select data-ms-part><option value=""${!part?' selected':''}>Choose a word part</option>${s.parts.map(x=>`<option value="${esc(x.id)}"${x.id===d.partId?' selected':''}>${esc(x.text)}</option>`).join('')}</select></label></div>${prefix?p(`Prefix clue: ${prefix.meaning}`):''}<div class="ms-sign">${signArt()}<div class="ms-painted"><span>${ready?letters:'<span class="ms-blank">?</span>'}</span></div></div>${ready?`<div class="ms-split">${esc(prefix.text)} <span aria-hidden="true">+</span> ${esc(part.text)}</div>${r.meaning!==null?`${p(r.meaning)}${r.boundary?p(`Both ${r.boundary} letters stay.`):''}`:`<div class="ms-discovery">${p(T.discovery)}${p(T.bigger)}</div>`}`:p('Choose both parts before keeping this sign.')}<div class="ms-actions">${button('keep-sign','Keep this sign','',!ready)}${button('clear-sign','Clear my sign','',d.prefixId===null&&d.partId===null)}</div><details class="ms-bigger"><summary>Check in a bigger dictionary</summary>${p(T.bigger)}</details>${panel(l,'kept','Kept signs',`${kept.length?`<div class="ms-kept-signs">${kept.slice(page*perPage,(page+1)*perPage).map((k,i)=>{const a=s.prefixes.find(p=>p.id===k.prefixId),b=s.parts.find(p=>p.id===k.partId);return button('reopen-sign',a.text+b.text,`data-ms-kept="${page*perPage+i}" aria-label="Reopen this sign: ${esc(a.text+b.text)}"`);}).join('')}</div><div class="ms-actions">${button('kept-prev','Previous signs','',page===0)}${p(`Page ${page+1} of ${pages}`)}${button('kept-next','Next signs','',page===pages-1)}</div>`:p('Your first kept sign will wait here.')}`)}</section>`;
}
const fill=(text,values)=>String(text??'').replace(/\{(\w+)\}/g,(all,key)=>values[key]??all);
